:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #f0f0f5;
  --text-muted: #a0a0b8;
  --accent: #6c5ce7;
  --accent-hover: #7f6ff0;
  --accent-pressed: #5a4bd1;
  --focus-ring: #fdcb6e;
  --swatch-radius: 12px;
  --card-radius: 20px;
  --font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background-image: radial-gradient(circle at 20% 30%, rgba(108, 92, 231, 0.15), transparent 50%),
                    radial-gradient(circle at 80% 70%, rgba(253, 203, 110, 0.08), transparent 50%);
}

.card {
  background: var(--card-bg);
  border-radius: var(--card-radius);
  padding: 32px 24px;
  width: 100%;
  max-width: 520px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 24px;
}

header {
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 6px;
}

.subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
  line-height: 1.4;
}

.swatches {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.swatch {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 12px 16px;
  border-radius: var(--swatch-radius);
  background: rgba(255, 255, 255, 0.06);
  border: 2px solid transparent;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.swatch:focus-within {
  border-color: var(--focus-ring);
  box-shadow: 0 0 0 3px rgba(253, 203, 110, 0.25);
}

.color-preview {
  width: 56px;
  height: 56px;
  border-radius: 10px;
  flex-shrink: 0;
  border: 2px solid rgba(255, 255, 255, 0.15);
  transition: background-color 0.3s ease;
}

.hex-code {
  font-family: "SF Mono", "Cascadia Code", Consolas, monospace;
  font-size: 1.1rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  flex: 1;
  text-transform: uppercase;
}

.lock-btn {
  background: rgba(255, 255, 255, 0.1);
  border: 2px solid transparent;
  color: var(--text-muted);
  font-size: 1.35rem;
  width: 44px;
  height: 44px;
  border-radius: 10px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s, color 0.2s, border-color 0.2s, transform 0.1s;
  flex-shrink: 0;
}

.lock-btn:hover {
  background: rgba(255, 255, 255, 0.18);
  color: var(--text);
}

.lock-btn:focus-visible {
  outline: none;
  border-color: var(--focus-ring);
  box-shadow: 0 0 0 3px rgba(253, 203, 110, 0.3);
}

.lock-btn:active {
  transform: scale(0.92);
}

.lock-btn[aria-pressed="true"] {
  color: var(--focus-ring);
  background: rgba(253, 203, 110, 0.15);
}

.generate-btn {
  font-family: var(--font);
  font-size: 1.05rem;
  font-weight: 600;
  padding: 16px 24px;
  border: none;
  border-radius: 12px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s, box-shadow 0.2s;
  letter-spacing: 0.01em;
}

.generate-btn:hover {
  background: var(--accent-hover);
}

.generate-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--bg), 0 0 0 6px var(--focus-ring);
}

.generate-btn:active {
  background: var(--accent-pressed);
  transform: scale(0.98);
}

.hint {
  font-size: 0.85rem;
  color: var(--text-muted);
  text-align: center;
  min-height: 1.2em;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
    gap: 20px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .color-preview {
    width: 48px;
    height: 48px;
  }
  .hex-code {
    font-size: 1rem;
  }
  .lock-btn {
    width: 40px;
    height: 40px;
    font-size: 1.2rem;
  }
  .swatch {
    gap: 12px;
    padding: 10px 12px;
  }
}

(function () {
  'use strict';

  var NUM_SWATCHES = 5;
  var swatchesEl = document.getElementById('swatches');
  var generateBtn = document.getElementById('generateBtn');
  var announcer = document.getElementById('announcer');

  var state = [];

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    var a = s * Math.min(l, 1 - l);
    var f = function (n) {
      var k = (n + h / 30) % 12;
      var color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return '#' + f(0) + f(8) + f(4);
  }

  function randomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  function generateHarmoniousPalette() {
    var baseHue = randomInt(0, 359);
    var scheme = randomInt(0, 2);
    var hues = [];
    var i;

    if (scheme === 0) {
      for (i = 0; i < NUM_SWATCHES; i++) {
        hues.push((baseHue + i * (360 / NUM_SWATCHES)) % 360);
      }
    } else if (scheme === 1) {
      var offsets = [0, 30, 180, 210, 330];
      for (i = 0; i < NUM_SWATCHES; i++) {
        hues.push((baseHue + offsets[i]) % 360);
      }
    } else {
      var offsets2 = [0, 15, 150, 180, 300];
      for (i = 0; i < NUM_SWATCHES; i++) {
        hues.push((baseHue + offsets2[i]) % 360);
      }
    }

    var palette = [];
    for (i = 0; i < NUM_SWATCHES; i++) {
      var sat = randomInt(55, 85);
      var light = randomInt(40, 65);
      palette.push(hslToHex(hues[i], sat, light));
    }
    return palette;
  }

  function render() {
    swatchesEl.innerHTML = '';
    state.forEach(function (swatch, index) {
      var item = document.createElement('div');
      item.className = 'swatch';
      item.setAttribute('role', 'listitem');

      var preview = document.createElement('div');
      preview.className = 'color-preview';
      preview.style.backgroundColor = swatch.color;
      preview.setAttribute('aria-hidden', 'true');

      var hex = document.createElement('span');
      hex.className = 'hex-code';
      hex.textContent = swatch.color.toUpperCase();

      var lockBtn = document.createElement('button');
      lockBtn.type = 'button';
      lockBtn.className = 'lock-btn';
      lockBtn.setAttribute('aria-pressed', String(swatch.locked));
      lockBtn.setAttribute('aria-label', (swatch.locked ? 'Unlock' : 'Lock') + ' color ' + swatch.color.toUpperCase());
      lockBtn.textContent = swatch.locked ? '\uD83D\uDD12' : '\uD83D\uDD13';

      lockBtn.addEventListener('click', function () {
        swatch.locked = !swatch.locked;
        render();
        announcer.textContent = 'Color ' + swatch.color.toUpperCase() + (swatch.locked ? ' locked' : ' unlocked') + '.';
      });

      item.appendChild(preview);
      item.appendChild(hex);
      item.appendChild(lockBtn);
      swatchesEl.appendChild(item);
    });
  }

  function generate() {
    var newColors = generateHarmoniousPalette();
    var lockedCount = 0;
    state = state.map(function (swatch, i) {
      if (swatch.locked) {
        lockedCount++;
        return swatch;
      }
      return { color: newColors[i], locked: false };
    });
    render();
    announcer.textContent = 'New palette generated. ' + lockedCount + ' color' + (lockedCount !== 1 ? 's' : '') + ' kept locked.';
  }

  function init() {
    var initial = generateHarmoniousPalette();
    state = initial.map(function (color) {
      return { color: color, locked: false };
    });
    render();
    generateBtn.addEventListener('click', generate);
  }

  init();
})();
